{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table maplemonk.ras_sales_data as WITH inventory as ( select case when i.brand IN (\"RBPL- MOODY\",\"MOODY\") THEN \"MOODY\" ELSE \"RAS\" END as Brand_name , i.sku , i.product_name from `MAPLEMONK.ras_inventory_fact_items` i ), sku_master as ( select sm.sku , sm.brand from `MAPLEMONK.ras_sku_master` sm ) select coalesce(i.Brand_name, case when sm.brand in (\"Moody Store\",\"Moody\",\"Moody Website\",\"B26779\") then \"MOODY\" else (case when sm.brand in (\"RAS LUXURY OILS\",\"RAS Luxury Oils India\",\"RAS Luxury Skincare\",\"RAS Luxury Oils\",\"RBPL - RAS\",\"RAS\",\"24KGOLDYOUDUO\",\"B12759\") then \"RAS\" else (case when sm.brand in(\"RBPL - RAS\") then \"RAS\" else \"MOODY\" end) end) end ) Brand_name , case when s.marketplace in (\"SHOPIFY\",\"SHOPIFYMARKETPLACE\",\"SHOPIFY2\",\"SHOPIFY14\",\"SHOPIFY13\") then \"D2C\" else (case when s.marketplace in (\"CRED-API2\",\"CRED-API\") then \"CRED\" else (case when s.marketplace in (\"FLIPKART\",\"AMAZON.IN\",\"AMAZON_FBA\",\"TATA CLIQ\",\"MYNTRA PPMP\",\"FIRSTCRY\") THEN \"MARKETPLACE\" else (case when s.marketplace in (\"B2B\",\"PRPDUCTION ORDER\",\"DEKIT ORDER\",\"ONEGREEN\",\"PRODUCTION ORDER\") then \"B2B\" else \"OFFLINE\" end ) end ) end ) end as Marketplace_Final , s.* from `MAPLEMONK.ras_sales_consolidated` s left join inventory i on s.sku=i.sku and s.product_name = i.product_name left join sku_master sm on sm.sku = s.sku; create or replace table maplemonk.ras_po_tracker as WITH grn_details as ( select g._id , g.grnId , cast(g.updated_at as timestamp) as grn_updated_date , g.po , g.invoice_id , cast(json_extract_scalar(skus,\'$.productName\') as string) as product_name , cast(json_extract_scalar(skus,\'$.taxPerItem\') as float64) as tax_per_item , cast(json_extract_scalar(skus,\'$.OriginalOrderedQuantity\') as int64) as original_order_quantity ,cast(json_extract_scalar(skus,\'$.totalReturnQuantity\') as int64) as total_returned_quantity , cast(json_extract_scalar(skus,\'$.unitTotal\') as float64) as total_units , cast(json_extract_scalar(skus,\'$.basePrice\') as float64) as base_price , cast(json_extract_scalar(skus,\'$.mrp\') as float64) as mrp , cast(json_extract_scalar(skus,\'$.taxRate\') as float64) as tax_rate , cast(json_extract_scalar(skus,\'$.netAmount\') as float64) as net_Amount , cast(json_extract_scalar(skus,\'$.batchCode\') as string) as batchCode from ( select * , cast(cast(po_number as int64) as string) as po , ROW_NUMBER() OVER (PARTITION BY cast(cast(po_number as int64) as string) ORDER BY updated_at DESC) as rw from `MAPLEMONK.edgistify_get_grn_details` ) g left join unnest(g.skus) as skus where rw = 1 ), po_details as ( select p.isActive , p.po_number , case when p.orderStatus in (\"PUT_AWAY\") then \"PUT AWAY\" else (case when p.orderStatus in (\"GRN_QC\") then \"GRN QC\" else (case when p.orderStatus in (\"PO_SENT\") then \"PO SENT\" else (case when p.orderStatus IN (\"PO_RECEIVED\") then \"PO RECEIVED\" else (case when p.orderStatus in (\"APPROVAL_PENDING\") then \"APPROVAL PENDING\" else p.orderStatus end)end)end)end)end AS orderStatus , safe_cast(p.poCreatedOn as timestamp) as pocreatedon , p.vendor_name , p.warehouse_name , p.shipping_partner , p.poReferenceNumber , p.orderStatusReadable , p.estimated_delivery_date from ( select * , ROW_NUMBER() OVER (PARTITION BY po_number order by pocreatedon desc) as rw from `MAPLEMONK.edgistify_get_po_list` ) p where rw = 1 ) select po.isActive , po.po_number , po.orderStatus , po.poCreatedOn , po.estimated_delivery_date , po.vendor_name , po.warehouse_name , po.shipping_partner , po.poReferenceNumber , po.orderStatusReadable , g.grn_updated_date , g.grnId , g.product_name , g.original_order_quantity , g.total_returned_quantity , g.total_units , g.invoice_id , g.batchCode , g.mrp , g.tax_rate , g.tax_per_item , g.net_Amount from po_details po left join grn_details g on g.po = po.po_number; create or replace table maplemonk.ras_sell_through_report as with sales_data as ( select s.product_name_final , last_day(s.ORDER_TIMESTAMP,month) as order_month_last_date , format_date(\'%B\' \'%Y\',last_day(s.order_date,month)) as order_month , count(QUANTITY) as order_quantity from maplemonk.ras_sales_data s group by 1,2,3 ), po_tracker as ( select p.po_number , p.isActive , p.product_name , p.orderStatus , safe_cast(p.poCreatedon as timestamp) as pocreatedon , format_date(\'%B\' \'%Y\',last_day(safe_cast(p.pocreatedon as date),month)) as po_created_month , p.warehouse_name , p.vendor_name , p.poReferenceNumber , p.original_order_quantity as po_original_order_quantity , p.total_returned_quantity as po_total_returned_quantity , p.batchCode from `MAPLEMONK.ras_po_tracker` p ) select p.po_number , p.isActive , p.product_name , s.product_name_final , s.order_month_last_date , s.order_month , s.order_quantity , p.orderStatus , p.poCreatedon , p.po_created_month , p.warehouse_name , p.vendor_name , p.poReferenceNumber , p.po_original_order_quantity , p.po_total_returned_quantity , p.batchCode from sales_data s left join po_tracker p on s.product_name_final = p.product_name;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            